for n in 3 4 5; do
  case $n in
    3) line='    focused_workspace #aabbcc #bbccdd #ccddee';;
    4) line='    focused_workspace #aabbcc #bbccdd #ccddee #ddeeff';;
    5) line='    focused_workspace #aabbcc #bbccdd #ccddee #ddeeff #eeff00';;
  esac
  cat > /tmp/ws_cfg <<EOF
bar {
  colors {
$line
  }
}
EOF
  for theme in solarized /tmp/custom_ws.yml; do
